 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The nonzero runs on the top/bottom edges are the color sequences.
    patterns = []
    for r in {0, h - 1}:
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            patterns.append(grid[r][start:c])

    # A lone interior color marks where its matching sequence is anchored.
    for r in range(1, h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for seq in patterns:
                if color in seq:
                    start = c - seq.index(color)
                    for i, value in enumerate(seq):
                        x = start + i
                        if 0 <= x < w:
                            out[r][x] = value
                    break
    return out
